mapper.select:
SELECT id AS image_id, object_key, NULL AS thumbnail_key
FROM review_image
WHERE review_id IS NULL
  AND created_at < #{createdBefore}
ORDER BY id
LIMIT #{limit}

mapper.delete:
DELETE FROM review_image
WHERE id = #{imageId}
  AND review_id IS NULL

mapper.select:
SELECT created_at
FROM review_image
WHERE member_id = #{memberId}
  AND review_id IS NULL
  AND created_at > #{createdAfter}
ORDER BY created_at
LIMIT #{limit}
